var tmpFileInput = document.createElement('input');
tmpFileInput.type = 'file';
tmpFileInput.id = 'upload_file';
tmpFileInput.name = 'upload_file';

tmpFileInput.onchange = function(fe) {
    var files = fe.currentTarget.files;
    doUploadDocumentFile(files, smrNumber, smdNumber);
}

tmpFileInput.click();


// 확장자 체크. sUtils.multipart.upload 에서 간헐적으로 체크를 실패하는 일이 있음
const fileName = files[0].name;
const lastDotIdx = fileName.lastIndexOf('.');
if (lastDotIdx == -1) {
    Alert('첨부가 제한된 확장자입니다');
    return false;
} else {
    const ext = fileName.slice(lastDotIdx + 1);
    if (['pdf', 'PDF', 'docx', 'doc', 'ppt', 'pptx', 'hwp'].indexOf(ext) == -1) {
        Alert(sUtils.string.dataReplacer(sUtils.cache.text.get("BASE_FILE.NOT_SUPPORT_EXT"), {
            EXT: ext
        }));
        return false;
    }
}

var config = {
    multiple: false,
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    ext: ['pdf', 'PDF', 'docx', 'doc', 'ppt', 'pptx', 'hwp'],
    on: {
        callback: function(res) {
            if (res.status == "1") {
                gridObj.cells(selectedGridId, gridObj.getColIndexById("DOC_NUMBER")).setValue(smrNumber + '_' + smdNumber);
                gridObj.cells(selectedGridId, gridObj.getColIndexById('ATTACH_IMG')).setIcon('ATTACH_IMG2');
                gridObj.cells(selectedGridId, gridObj.getColIndexById('ATTACH_IMG')).cell.children[0].style = 'filter:none';
                if(sUtils.workflow.check('USW1666240969042')){
                	gridObj.cells(selectedGridId, gridObj.getColIndexById("SUBJECT")).setValue(files[0].name);
                }
                openDocumentFile(smrNumber, smdNumber);
                formObj.checkItem('SEAL_IMG_FLAG');
