           		var FlagArray = new Array();
           		for(var j = 0; j < AllManageArray[i].length; j++){ //행 안의 인장 갯수만큼

            		if(defaultCorpSeal.indexOf(AllManageArray[i][j]) > -1){
            			FlagArray.push("true");
            		}
           		}
	            if(FlagArray.indexOf("true") == -1){
            		Alert("모든 서류에 법인인감을 날인해주세요.");
            		return;
            	}
           	}

            var realFlag = formObj.getValue('REAL_FLAG');
            if(!seal_choice && realFlag =='1'){
            	Alert(Sepoa.cache.text.get('SLM_211.SEAL_CHOICE'));
            	return;
            }

            Confirm(Sepoa.cache.text.get('SLM_211.MESSAGE_APPROVAL_REQUEST'), function(flag) {
                if (flag) {
                    doSave({
                        CALLBACK: doSetApproval,
                        CALLBACK_PARMETER: {
                            APPROVAL_PRC_TYPE: "APPROVAL_REQUEST"
                        }
                    });
                }
            });


            doServiceAjax('sepoa.svc.iams.SepoaIamsService', 'TRANSACTION', 'sendApproval', {
		SMR_NUMBER: $reqSealInfo.SMR_NUMBER
            }, function(so) {
                if (so.status == 1) {
		    var width = Math.min(SUX.root.innerWidth * 0.7, 1280);
		    var height = Math.min((SUX.root.innerHeight - 100) * 0.9, 800);
		    //var win = PopupOpenPostReal(so.result[0], width, height, Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'));
			var win = window.open(so.result[0], Sepoa.cache.text.get('SLM_221.APPLINE_SETTING'), "width=" + width + ",height=" + height );
			setTimeout(function run() {
				if(win.closed) {
				    if (Sepoa.request.SMR_NUMBER) {
					doQuery(Sepoa.request.SMR_NUMBER);
				    } else if (smrStatus == 'T' && moveFlag == 'Y') {
					linkTo('SLM_200', '/Seal/Document/Request/SealDocumentRequestLayout.sux', 'undefined', Sepoa.cache.text.get('SLM_211.REQUEST_LIST'));
					SUX.root.getContentsCell(window).close();
				    } else {
					doBack();
				    }
				} else {
					setTimeout(run, 500);
				}
			}, 500);
		} else {
			Alert(so.message);
		}
	});


